import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with shared memory
matrix_mul_shared_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matrix_mul_shared_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float s_A[TILE_SIZE][TILE_SIZE];
    __shared__ float s_B[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles into shared memory
        int t_row = t * TILE_SIZE + threadIdx.y;
        int t_col = t * TILE_SIZE + threadIdx.x;

        if (t_row < N && col < N) {
            s_A[threadIdx.y][threadIdx.x] = A[row * N + t_col];
        } else {
            s_A[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (t_col < N && row < N) {
            s_B[threadIdx.y][threadIdx.x] = B[t_row * N + col];
        } else {
            s_B[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += s_A[threadIdx.y][k] * s_B[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matrix_mul_shared_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matrix_mul_shared_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matrix_mul_shared_cpp_source = "torch::Tensor matrix_mul_shared_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code for matrix multiplication with shared memory
matrix_mul_shared = load_inline(
    name="matrix_mul_shared",
    cpp_sources=matrix_mul_shared_cpp_source,
    cuda_sources=matrix_mul_shared_source,
    functions=["matrix_mul_shared_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matrix_mul_shared = matrix_mul_shared

    def forward(self, A, B):
        return self.matrix_mul_shared.matrix_mul_shared_cuda(A, B)"}

